<script setup lang="ts">
// Author by Lab | zefry
import { computed, onBeforeUnmount, ref } from 'vue';
import { locale } from '../../i18n';
import ControlOperations from '../../components/ControlOperations.vue';
import LanguageSwitcher from '../../components/LanguageSwitcher.vue';
import WorkspaceIcon from '../../components/WorkspaceIcon.vue';
const tr = (id: string, en: string) => locale.value === 'id' ? id : en;
type Row = { id: string; name: string; email: string; status: string; version: number; tenant_id: string; created_at: number };
type Message = { id: string; tenant_id: string; status: string; attempts: number; safe_code: string | null; created_at: number };
type Settings = { version: number; enabled: boolean; host: string; port: number; username: string; from: string; from_name: string; dkim_selector: string; per_minute: number; password_configured: boolean };
const props = defineProps<{ control: Record<string, any>; registrations?: Record<string,{phone:string;business_type:string}>; businesses: { total: number; rows: Row[]; audit: { id: number; action: string; reason: string; occurred_at: number }[] }; mail: { total: number; counts: Record<string, number>; heartbeat_at: number; paused_until: number; suppressed_recipients: number; oldest_queued_at: number | null; messages: Message[]; events: { id: string; message_id: string; event: string; safe_code: string; occurred_at: number }[] }; settings: Settings; feedback_configured: boolean; page: number; mail_page: number }>();
const tab = ref(['overview','business','configuration','errors','marketing','mail','smtp','security','audit'].includes(window.location.hash.slice(1)) ? window.location.hash.slice(1) : 'overview'); const busy = ref(false); const uncertain = ref(false); const message = ref('');
const pending = ref<{ path: string; body: Record<string, unknown> } | null>(null);
const detail = ref<Record<string, any> | null>(null);
const navigation: [string,string,string,string][] = [['overview','activity','Ringkasan NOC','NOC overview'],['business','building-2','Akun bisnis','Business accounts'],['configuration','settings-2','Konfigurasi fitur','Feature configuration'],['errors','server','Insiden & error','Incidents & errors'],['marketing','megaphone','Marketing','Marketing'],['mail','mail','Laporan email','Mail reports'],['smtp','settings','Pengaturan SMTP','SMTP settings'],['security','shield-check','Keamanan','Security'],['audit','history','Riwayat aktivitas','Activity history']];
async function openBusiness(id: string) {
    if (busy.value || uncertain.value) return;
    busy.value = true;
    try { const r = await fetch('/platform/control/businesses/' + id, { headers: { Accept: 'application/json' }, credentials: 'same-origin' }); if (!r.ok) throw new Error(); detail.value = await r.json(); }
    catch { message.value = tr('Detail akun belum tersedia. Muat ulang halaman.', 'Account details unavailable. Reload the page.'); }
    finally { busy.value = false; }
}
const name = ref(''); const email = ref(''); const language = ref('id'); const reason = ref('');
const settings = ref({ ...props.settings, password: '' }); const password = ref(''); const code = ref('');
const testRecipient=ref('');
const retryId = ref(''); const duplicate = ref(false); const inspection = ref<Record<string, unknown> | null>(null);
const now = Math.floor(Date.now() / 1000);
function preventLostRequest(event: BeforeUnloadEvent) { if (busy.value || uncertain.value) { event.preventDefault(); event.returnValue = ''; } }
window.addEventListener('beforeunload', preventLostRequest);
onBeforeUnmount(() => window.removeEventListener('beforeunload', preventLostRequest));
const workerHealthy = computed(() => props.mail.heartbeat_at > now - 180);
const date = (value: number) => new Date(value * 1000).toLocaleString(locale.value === 'id' ? 'id-ID' : 'en-GB');
const statuses: Record<string, [string, string]> = { pending: ['Belum diverifikasi', 'Not verified'], invited: ['Undangan dikirim ke antrean', 'Invitation queued'], active: ['Aktif', 'Active'], suspended: ['Ditangguhkan', 'Suspended'], cancelled: ['Dibatalkan', 'Cancelled'], queued: ['Dalam antrean', 'Queued'], sending: ['Sedang dikirim', 'Sending'], accepted: ['Diterima SMTP', 'SMTP accepted'], delivered: ['Terkirim terkonfirmasi', 'Delivery confirmed'], retry: ['Menunggu coba ulang', 'Retry scheduled'], deferred: ['Ditunda oleh penyedia', 'Provider deferred'], soft_bounce: ['Terpental sementara', 'Soft bounce'], failed: ['Gagal', 'Failed'], unknown: ['Hasil tidak pasti', 'Unknown outcome'], hard_bounce: ['Terpental permanen', 'Hard bounce'], complaint: ['Keluhan spam', 'Spam complaint'], suppressed: ['Dihentikan untuk penerima', 'Recipient suppressed'] };
const status = (key: string) => statuses[key]?.[locale.value === 'id' ? 0 : 1] ?? key;
function headers() { return { 'Content-Type': 'application/json', Accept: 'application/json', 'X-CSRF-TOKEN': document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content ?? '' }; }
async function save(path: string, body: Record<string, unknown>) {
    if (busy.value) return;
    pending.value ??= { path, body: JSON.parse(JSON.stringify({ operation_id: crypto.randomUUID(), ...body })) }; busy.value = true; message.value = '';
    try {
        const r = await fetch(pending.value.path, { method: 'POST', credentials: 'same-origin', headers: headers(), body: JSON.stringify(pending.value.body) });
        if (r.status >= 500) throw new Error('uncertain');
        if (!r.ok) { detail.value = null; pending.value = null; uncertain.value = false; message.value = tr('Perubahan ditolak. Periksa isian, versi data, dan verifikasi keamanan. Jika sesi kedaluwarsa, muat ulang halaman.', 'Change denied. Check fields, data version, and security verification. Reload if your session expired.'); return; }
        const result = await r.json(); if (result.status === 'queued') {pending.value=null;uncertain.value=false;message.value=tr('Email uji masuk antrean. Lihat Laporan email untuk hasil pengiriman. ID: ','Test email queued. Check Mail reports for delivery. ID: ')+(result.record?.message_id??'');return;} if (result.status !== 'saved') throw new Error('uncertain');
        pending.value = null; uncertain.value = false; busy.value = false; window.location.assign('/platform?updated=' + Date.now() + '#' + tab.value);
    } catch { detail.value = null; uncertain.value = true; message.value = tr('Hasil belum pasti. Ulangi permintaan yang sama menggunakan tombol di bawah.', 'The result is uncertain. Retry the same request below.'); }
    finally { busy.value = false; }
}
function create() { void save('/platform/businesses', { operation_id: crypto.randomUUID(), action: 'create', name: name.value, email: email.value, locale: language.value, reason: reason.value }); }
function change(row: Row, action: string) { void save('/platform/businesses', { operation_id: crypto.randomUUID(), action, id: row.id, version: Number(row.version), reason: reason.value }); }
function configure() { const { password_configured: _, ...body } = settings.value; void save('/platform/mail/settings', body); }
async function verify() {
    busy.value = true; message.value = '';
    try {
        const r = await fetch('/auth/reauthenticate/privileged', { method: 'POST', credentials: 'same-origin', headers: headers(), body: JSON.stringify({ password: password.value, code: code.value }) });
        if (r.ok) { busy.value = false; window.location.assign('/platform?updated=' + Date.now() + '#' + tab.value); } else message.value = tr('Verifikasi gagal. MFA dan verifikasi ulang harus aktif untuk pemilik platform.', 'Verification failed. MFA and step-up must be enabled for the platform owner.');
    } catch { message.value = tr('Verifikasi belum berhasil.', 'Verification did not complete.'); }
    finally { password.value = ''; code.value = ''; busy.value = false; }
}
async function inspect() {
    busy.value = true;
    try { const r = await fetch('/platform/mail/inspect', { headers: { Accept: 'application/json' } }); if (!r.ok) throw new Error(); inspection.value = await r.json(); }
    catch { message.value = tr('Pemeriksaan DNS belum berhasil. Coba kembali nanti.', 'DNS inspection did not complete. Try again later.'); }
    finally { busy.value = false; }
}
</script>
<template>
    <main class="platform">
        <aside class="control-sidebar"><a class="control-logo" href="/platform"><span>q</span>oneQay</a><p class="sidebar-label">CONTROL PLANE</p><nav aria-label="Platform"><button v-for="[key, icon, id, en] in navigation" :key="key" :class="{ selected: tab === key }" @click="tab = key"><WorkspaceIcon :name="icon" :size="18"/><span>{{ tr(id,en) }}</span></button><a href="/platform/site"><WorkspaceIcon name="panels-top-left" :size="18"/>{{ tr('Editor website','Website editor') }} ↗</a></nav><div class="sidebar-foot"><span class="live-dot"/>{{ tr('Akses pemilik platform','Platform owner access') }}<small>© {{ new Date().getFullYear() }} oneQay</small></div></aside>
        <div class="control-content"><div class="control-topbar"><span>{{ tr('Platform / Operasional','Platform / Operations') }}</span><div><a href="/pos">{{ tr('Ruang kerja bisnis','Business workspace') }} ↗</a><LanguageSwitcher/></div></div>
        <header class="hero"><div><a href="/pos">← {{ tr('Ruang kerja bisnis', 'Business workspace') }}</a><p class="eyebrow">ONEQAY / {{ tr('PEMILIK PLATFORM', 'PLATFORM OWNER') }}</p><h1>{{ tr('Kendali penuh. Bisnis bertumbuh.', 'In control. Ready to grow.') }}</h1><p>{{ tr('Kelola bisnis, keamanan, dan kesehatan layanan oneQay dari satu pusat kendali.', 'Manage businesses, security, and oneQay service health from one control center.') }}</p></div><span class="owner">{{ tr('Akses khusus pemilik', 'Owner access') }}</span></header>
        <section v-if="['mail','smtp'].includes(tab)" class="metrics"><article><span>{{ tr('Bisnis terdaftar', 'Registered businesses') }}</span><strong>{{ businesses.total }}</strong></article><article><span>{{ tr('Email antre / coba ulang', 'Queued / retrying mail') }}</span><strong>{{ Number(mail.counts.queued ?? 0) + Number(mail.counts.retry ?? 0) }}</strong></article><article><span>{{ tr('Penerima dihentikan', 'Suppressed recipients') }}</span><strong>{{ mail.suppressed_recipients }}</strong></article><article :class="{ warn: !workerHealthy }"><span>{{ tr('Kesehatan cron', 'Cron health') }}</span><strong class="health">{{ workerHealthy ? tr('Berjalan', 'Running') : tr('Perlu perhatian', 'Needs attention') }}</strong><small>{{ mail.heartbeat_at ? date(mail.heartbeat_at) : tr('Belum ada aktivitas worker', 'No worker heartbeat yet') }}</small></article></section>
        <div v-if="mail.paused_until > now" class="notice">{{ tr('Pengiriman dijeda sementara setelah beberapa kegagalan SMTP. Percobaan dilanjutkan setelah', 'Sending temporarily paused after repeated SMTP failures. Attempts resume after') }} {{ date(mail.paused_until) }}.</div>
        <div v-if="message" role="status" class="notice">{{ message }} <button v-if="uncertain && pending" :disabled="busy" @click="save(pending.path, pending.body)">{{ tr('Ulangi permintaan yang sama', 'Retry same request') }}</button></div>
        <div class="action-context"><label>{{ tr('Catatan tindakan untuk jejak aktivitas','Action note for the activity log') }}<input v-model="reason" maxlength="300" :placeholder="tr('Tuliskan alasan perubahan…','Describe the reason for your change…')"/></label><button @click="tab = 'security'"><WorkspaceIcon name="shield-check" :size="15"/>{{ tr('Verifikasi keamanan','Security verification') }}</button></div>
        <ControlOperations :control="control" :tab="tab" :detail="detail" :busy="busy || uncertain" :reason="reason" @reason="reason = $event" @close="detail = null" @command="save('/platform/control/commands', $event)"/>

        <section v-if="tab === 'business'" class="columns"><article class="card"><h2>{{ tr('Daftarkan bisnis', 'Register a business') }}</h2><form @submit.prevent="create"><fieldset :disabled="busy || uncertain"><label>{{ tr('Nama bisnis', 'Business name') }}<input v-model="name" required maxlength="160" /></label><label>{{ tr('Email pemilik bisnis', 'Business owner email') }}<input v-model="email" type="email" required maxlength="254" /></label><label>{{ tr('Bahasa undangan', 'Invitation language') }}<select v-model="language"><option value="id">Bahasa Indonesia</option><option value="en">English</option></select></label><label>{{ tr('Catatan / alasan tindakan', 'Action note / reason') }}<input v-model="reason" required maxlength="300" /></label><button class="primary">{{ tr('Daftarkan bisnis', 'Register business') }}</button></fieldset></form><p class="hint">{{ tr('Pendaftaran mandiri langsung menerima tautan verifikasi email tanpa persetujuan manual. Untuk akun yang Anda buat di sini, kirim tautan aktivasi. Pemilik membuat kata sandi sendiri.', 'Self-registration sends an email verification link without manual approval. Send activation links for accounts you create here. Owners set their own passwords.') }}</p></article><article class="card wide"><h2>{{ tr('Daftar bisnis', 'Business directory') }}</h2><p class="hint">{{ tr('Isi catatan tindakan sebelum mengubah status. Penangguhan mencabut sesi bisnis; aktivasi ulang memerlukan login baru.', 'Enter an action note before changing status. Suspension revokes business sessions; resumption requires a fresh login.') }}</p><div class="table"><table><thead><tr><th>{{ tr('Bisnis', 'Business') }}</th><th>Status</th><th>{{ tr('Tindakan', 'Actions') }}</th></tr></thead><tbody><tr v-for="row in businesses.rows" :key="row.id"><td><strong>{{ row.name }}</strong><small>{{ row.email }}</small><small v-if="registrations?.[row.id]">{{ registrations[row.id].phone }} · {{ registrations[row.id].business_type }}</small><small>ID: {{ row.id }}</small></td><td><span class="badge" :class="row.status">{{ status(row.status) }}</span></td><td><div class="actions"><button :disabled="busy || uncertain" @click="openBusiness(row.id)">{{ tr('Kelola akun', 'Manage account') }}</button><button v-if="['pending', 'invited'].includes(row.status)" :disabled="busy || uncertain || !reason.trim()" @click="change(row, 'invite')">{{ row.status === 'pending' ? tr('Kirim tautan aktivasi', 'Send activation link') : tr('Perbarui undangan', 'Renew invitation') }}</button><button v-if="['pending', 'invited'].includes(row.status)" :disabled="busy || uncertain || !reason.trim()" @click="change(row, 'cancel')">{{ tr('Batalkan', 'Cancel') }}</button><button v-if="row.status === 'active'" :disabled="busy || uncertain || !reason.trim()" @click="change(row, 'suspend')">{{ tr('Tangguhkan', 'Suspend') }}</button><button v-if="row.status === 'suspended'" :disabled="busy || uncertain || !reason.trim()" @click="change(row, 'resume')">{{ tr('Aktifkan kembali', 'Resume') }}</button></div></td></tr><tr v-if="!businesses.rows.length"><td colspan="3">{{ tr('Belum ada bisnis. Mulai dengan formulir pendaftaran.', 'No businesses yet. Start with the registration form.') }}</td></tr></tbody></table></div><div class="pagination"><a v-if="page > 1" :href="`/platform?page=${page - 1}`">← {{ tr('Sebelumnya', 'Previous') }}</a><span>{{ tr('Halaman', 'Page') }} {{ page }}</span><a v-if="page * 25 < businesses.total" :href="`/platform?page=${page + 1}`">{{ tr('Berikutnya', 'Next') }} →</a></div></article></section>
        <section v-if="tab === 'mail'" class="card"><h2>{{ tr('Status pengiriman', 'Delivery status') }}</h2><p class="hint">{{ tr('Diterima SMTP berarti server menerima pesan, belum membuktikan pesan masuk ke inbox. Konfirmasi terkirim/bounce memerlukan umpan balik penyedia.', 'SMTP accepted means the server accepted the message; it does not prove inbox delivery. Delivered/bounce confirmation requires provider feedback.') }}</p><p class="notice" v-if="!feedback_configured">{{ tr('Kunci integrasi laporan pengiriman belum dikonfigurasi. Hubungkan umpan balik penyedia agar bounce dan konfirmasi pengiriman diterima.', 'Delivery feedback integration key is not configured. Connect provider feedback to receive bounces and delivery confirmations.') }}</p><div class="counts"><span v-for="(count, key) in mail.counts" :key="key">{{ status(String(key)) }} <b>{{ count }}</b></span></div><div class="table"><table><thead><tr><th>ID</th><th>Status</th><th>{{ tr('Percobaan', 'Attempts') }}</th><th>{{ tr('Laporan', 'Report') }}</th><th>{{ tr('Tindakan', 'Action') }}</th></tr></thead><tbody><tr v-for="row in mail.messages" :key="row.id"><td><code>{{ row.id.slice(0, 12) }}</code><small>{{ date(row.created_at) }}</small></td><td>{{ status(row.status) }}</td><td>{{ row.attempts }}</td><td>{{ row.safe_code }}</td><td><button v-if="['failed', 'unknown'].includes(row.status)" :disabled="busy || uncertain" @click="retryId = row.id; duplicate = false">{{ tr('Tinjau & coba ulang', 'Review & retry') }}</button></td></tr><tr v-if="!mail.messages.length"><td colspan="5">{{ tr('Belum ada email dalam antrean.', 'No email has been queued.') }}</td></tr></tbody></table></div><div class="pagination"><a v-if="mail_page > 1" :href="`/platform?mail_page=${mail_page - 1}#mail`">← {{ tr('Sebelumnya', 'Previous') }}</a><span>{{ tr('Halaman', 'Page') }} {{ mail_page }}</span><a v-if="mail_page * 25 < mail.total" :href="`/platform?mail_page=${mail_page + 1}#mail`">{{ tr('Berikutnya', 'Next') }} →</a></div><form v-if="retryId" class="notice" @submit.prevent="save('/platform/mail/retry', { id: retryId, reason, accept_duplicate_risk: duplicate })"><fieldset :disabled="busy || uncertain"><strong>{{ tr('Coba ulang email', 'Retry email') }} {{ retryId.slice(0, 12) }}</strong><label>{{ tr('Alasan coba ulang', 'Retry reason') }}<input v-model="reason" required maxlength="300" /></label><label class="check"><input type="checkbox" v-model="duplicate" />{{ tr('Untuk hasil tidak pasti: saya telah meninjau log penyedia dan menerima risiko email ganda.', 'For an unknown outcome: I reviewed provider logs and accept the risk of duplicate email.') }}</label><button>{{ tr('Coba ulang', 'Retry') }}</button></fieldset></form><h3>{{ tr('Riwayat pengiriman terbaru', 'Recent delivery events') }}</h3><ul class="history"><li v-for="event in mail.events" :key="event.id"><time>{{ date(event.occurred_at) }}</time><span>{{ status(event.event) }}</span><code>{{ event.safe_code }}</code></li></ul></section>
        <section v-if="tab === 'smtp'" class="columns"><article class="card"><h2>{{ tr('Pengaturan SMTP aman', 'Secure SMTP settings') }}</h2><form @submit.prevent="configure"><fieldset :disabled="busy || uncertain"><label class="check"><input type="checkbox" v-model="settings.enabled" />{{ tr('Aktifkan pengiriman email transaksi', 'Enable transactional email sending') }}</label><label>SMTP host<input v-model="settings.host" required maxlength="253" placeholder="mail.example.com" /></label><label>Port / TLS<select v-model.number="settings.port"><option :value="465">465 · TLS</option><option :value="587">587 · STARTTLS required</option></select></label><label>{{ tr('Username SMTP', 'SMTP username') }}<input v-model="settings.username" required autocomplete="off" /></label><label>{{ tr('Kata sandi SMTP', 'SMTP password') }}<input v-model="settings.password" type="password" autocomplete="new-password" :placeholder="settings.password_configured ? tr('Kosongkan untuk mempertahankan', 'Leave blank to retain') : ''" /></label><label>{{ tr('Email pengirim', 'Sender email') }}<input v-model="settings.from" type="email" required /></label><label>{{ tr('Nama pengirim', 'Sender name') }}<input v-model="settings.from_name" required maxlength="120" /></label><label>DKIM selector<input v-model="settings.dkim_selector" required maxlength="63" /></label><label>{{ tr('Batas email per menit', 'Messages per minute') }}<input v-model.number="settings.per_minute" type="number" min="1" max="60" required /></label><button class="primary">{{ tr('Simpan pengaturan', 'Save settings') }}</button></fieldset></form></article><aside class="card"><h2>{{ tr('Kesehatan domain pengirim', 'Sender domain health') }}</h2><p>{{ tr('Gunakan SPF, DKIM, dan DMARC yang selaras dengan domain pengirim. Penyedia SMTP harus menandatangani pesan dengan DKIM dan mengelola PTR serta reputasi IP.', 'Use SPF, DKIM and DMARC aligned with the sender domain. Your SMTP provider must DKIM-sign messages and manage PTR and IP reputation.') }}</p><button :disabled="busy || uncertain" @click="inspect">{{ tr('Periksa DNS sekarang', 'Check DNS now') }}</button><dl v-if="inspection"><template v-for="field in [['smtp_public_dns', 'DNS SMTP publik', 'Public SMTP DNS'], ['spf_record_present', 'Rekaman SPF', 'SPF record'], ['dkim_record_present', 'Rekaman DKIM', 'DKIM record'], ['dmarc_record_present', 'Rekaman DMARC', 'DMARC record']]" :key="field[0]"><dt>{{ tr(field[1], field[2]) }}</dt><dd>{{ inspection[field[0]] ? tr('Ditemukan', 'Found') : tr('Belum terverifikasi', 'Not verified') }}</dd></template></dl><p class="hint">{{ tr('Pemeriksaan ini mendeteksi keberadaan rekaman DNS, bukan membuktikan tanda tangan atau menjamin inbox. Isi autentikasi yang benar sesuai petunjuk penyedia.', 'This checks DNS record presence, not actual signing or guaranteed inbox placement. Configure authentication according to your provider.') }}</p><form @submit.prevent="save('/platform/mail/test',{recipient:testRecipient})"><h3>{{tr('Tes pengiriman SMTP','SMTP delivery test')}}</h3><p class="hint">{{tr('Simpan konfigurasi dahulu. Tes memakai antrean dan worker yang sama dengan email verifikasi. Status antre bukan berarti sudah diterima penerima.','Save configuration first. This uses the same queue and worker as verification mail. Queued does not mean delivered.')}}</p><label>{{tr('Email penerima tes','Test recipient email')}}<input v-model="testRecipient" type="email" required maxlength="254" autocomplete="email"/></label><button class="primary" :disabled="busy||uncertain||!settings.enabled">{{tr('Kirim email tes','Send test email')}}</button></form><h3>{{ tr('Pemrosesan melalui cron', 'Cron processing') }}</h3><p>{{ tr('Jalankan perintah oneqay:control:work setiap menit menggunakan PHP hosting. Dashboard menampilkan waktu aktivitas terakhir.', 'Run oneqay:control:work every minute using hosting PHP. The dashboard shows the last heartbeat.') }}</p><h3>{{ tr('Laporan bounce', 'Bounce feedback') }}</h3><p>{{ tr('Hubungkan adaptor penyedia ke /platform/mail/feedback dengan HMAC. Kunci rahasia disimpan pada konfigurasi privat hosting.', 'Connect your provider adapter to /platform/mail/feedback with HMAC. The secret stays in private hosting configuration.') }}</p></aside></section>
        <section v-if="tab === 'security'" class="card security"><h2>{{ tr('Verifikasi pemilik platform', 'Verify platform owner') }}</h2><p>{{ tr('Perubahan lintas bisnis dan SMTP memerlukan kata sandi serta kode authenticator. Verifikasi berlaku lima menit.', 'Cross-business and SMTP changes require your password and authenticator code. Verification is valid for five minutes.') }}</p><form @submit.prevent="verify"><fieldset :disabled="busy || uncertain"><label>{{ tr('Kata sandi akun', 'Account password') }}<input v-model="password" type="password" required autocomplete="current-password" /></label><label>{{ tr('Kode authenticator', 'Authenticator code') }}<input v-model="code" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" /></label><button class="primary">{{ tr('Verifikasi', 'Verify') }}</button></fieldset></form></section>
        <section v-if="tab === 'audit'" class="card audit"><h2>{{ tr('Jejak aktivitas pemilik', 'Owner activity log') }}</h2><ul class="history"><li v-for="event in businesses.audit" :key="event.id"><time>{{ date(event.occurred_at) }}</time><b>{{ event.action }}</b><span>{{ event.reason }}</span></li><li v-if="!businesses.audit.length">{{ tr('Belum ada aktivitas.', 'No activity yet.') }}</li></ul></section><footer>Copyright oneQay</footer>
    </div></main>
